blocks.description:
Block: ESP32 DevKit

prop.noditronKind: esp32-devkit
prop.connectionState: disconnected
prop.dialog: container.style.fontFamily = 'Inter, sans-serif';

const heading = document.createElement('h3');
heading.textContent = 'ESP32 DEVKIT';
heading.style.cssText = 'margin:0 0 14px;color:var(--success,#3ecf5d);font-size:15px;letter-spacing:.03em;';
container.appendChild(heading);

const status = document.createElement('p');
status.textContent = 'Not connected. This board has no known firmware yet.';
status.style.cssText = 'margin:0 0 14px;font-size:12px;color:var(--text-muted);';
container.appendChild(status);

function section(labelText) {
  const wrap = document.createElement('div');
  wrap.style.cssText = 'margin-bottom:14px;';
  const label = document.createElement('div');
  label.textContent = labelText;
  label.style.cssText = 'font-size:11px;font-weight:700;letter-spacing:.05em;color:var(--text-muted);margin-bottom:6px;';
  wrap.appendChild(label);
  container.appendChild(wrap);
  return wrap;
}

const connectSection = section('CONNECT VIA');
const btnRow = document.createElement('div');
btnRow.style.cssText = 'display:flex;gap:8px;flex-wrap:wrap;';
const btnStyle = 'padding:6px 10px;border:1px solid var(--border);border-radius:6px;background:none;color:var(--text-primary);font-size:12px;cursor:pointer;';
['Serial port', 'WebSocket', 'IP address'].forEach((label) => {
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.textContent = label;
  btn.style.cssText = btnStyle;
  btn.disabled = true;
  btnRow.appendChild(btn);
});
connectSection.appendChild(btnRow);

const hint = document.createElement('p');
hint.textContent = 'Connecting and firmware detection are not wired up yet -- this dialog is a placeholder for that step.';
hint.style.cssText = 'margin:0;font-size:11px;color:var(--text-muted);';
container.appendChild(hint);

